// Illustrated SVG destination scenes used in place of photography (no licensed photos bundled).
(function () {
  const svg = (body, label) => `<svg viewBox="0 0 400 260" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${label}">${body}</svg>`;
  const S = {
    santorini: () => svg(`<rect width="400" height="260" fill="#7DD3FC"/><rect y="170" width="400" height="90" fill="#0369A1"/><path d="M0 180 L60 130 h60 l20 26 h60 l20 -40 h80 l30 34 h70 V260 H0Z" fill="#F8FAFC"/>${[[90, 130, 24], [240, 116, 30], [340, 150, 18]].map(([x, y, r]) => `<path d="M${x - r} ${y} a${r} ${r} 0 0 1 ${r * 2} 0Z" fill="#1D4ED8"/>`).join("")}${Array.from({ length: 8 }, (_, i) => `<rect x="${20 + i * 46}" y="${176 + (i % 3) * 16}" width="24" height="18" fill="#E2E8F0"/><rect x="${28 + i * 46}" y="${181 + (i % 3) * 16}" width="8" height="12" fill="#2563EB"/>`).join("")}`, "Santorini blue domes"),
    cancun: () => svg(`<rect width="400" height="260" fill="#22D3EE"/><rect y="0" width="400" height="90" fill="#BAE6FD"/><path d="M0 170 Q200 140 400 180 V260 H0Z" fill="#FEF3C7"/>${[[300, 1], [350, .8]].map(([x, s]) => `<g transform="translate(${x} 260) scale(${s})"><path d="M0 0 Q-10 -90 10 -160" stroke="#78350F" stroke-width="9" fill="none"/>${[-60, -25, 15, 55].map((a) => `<path d="M10 -160 q${a} -24 ${a * 1.5} 22" stroke="#15803D" stroke-width="12" fill="none" stroke-linecap="round"/>`).join("")}</g>`).join("")}<rect x="60" y="190" width="70" height="8" rx="3" fill="#F97316"/><path d="M60 190 L95 150 L130 190" fill="#FB923C"/>`, "Cancún beach with palm trees"),
    kyoto: () => svg(`<rect width="400" height="260" fill="#FED7AA"/><circle cx="310" cy="70" r="34" fill="#FB923C" opacity=".7"/><g fill="#7C2D12"><rect x="190" y="60" width="20" height="170"/>${[0, 1, 2, 3, 4].map((i) => `<path d="M${140 + i * 10} ${70 + i * 32} h${120 - i * 20} l-12 12 h${-(96 - i * 20)} z" fill="#1F2937"/>`).join("")}</g><rect y="228" width="400" height="32" fill="#57534E"/>${Array.from({ length: 30 }, (_, i) => `<circle cx="${(i * 41) % 400}" cy="${(i * 17) % 80 + 10}" r="${6 + (i % 3) * 4}" fill="#FBCFE8"/>`).join("")}`, "Kyoto pagoda among blossoms"),
    amalfi: () => svg(`<rect width="400" height="260" fill="#BAE6FD"/><rect y="200" width="400" height="60" fill="#0284C7"/><path d="M0 70 L120 30 L260 60 L400 20 V210 H0Z" fill="#65A30D"/>${Array.from({ length: 30 }, (_, i) => `<rect x="${16 + (i % 10) * 38}" y="${92 + Math.floor(i / 10) * 36 - (i % 10) * 3}" width="32" height="32" fill="${["#FDBA74", "#FCA5A5", "#FDE68A", "#F9A8D4", "#FFFFFF"][i % 5]}"/>`).join("")}`, "Amalfi coast village"),
    maldives: () => svg(`<rect width="400" height="260" fill="#67E8F9"/><rect y="0" width="400" height="80" fill="#E0F2FE"/>${[60, 150, 240, 330].map((x) => `<rect x="${x - 2}" y="120" width="4" height="70" fill="#78350F"/><rect x="${x - 30}" y="118" width="60" height="30" fill="#FDE68A"/><path d="M${x - 38} 120 L${x} 92 L${x + 38} 120Z" fill="#A16207"/>`).join("")}<rect x="0" y="146" width="400" height="6" fill="#78350F"/>${Array.from({ length: 6 }, (_, i) => `<path d="M${i * 70} ${210 + (i % 2) * 14} q20 -6 40 0" stroke="#fff" stroke-width="2" fill="none" opacity=".6"/>`).join("")}`, "Maldives overwater villas"),
    iceland: () => svg(`<rect width="400" height="260" fill="#0B1530"/>${Array.from({ length: 40 }, (_, i) => `<circle cx="${(i * 97) % 400}" cy="${(i * 41) % 140}" r="1.2" fill="#fff"/>`).join("")}<path d="M-20 120 Q100 30 220 110 T420 70" stroke="#34D399" stroke-width="40" fill="none" opacity=".45"/><path d="M0 210 L120 150 L200 190 L300 140 L400 200 V260 H0Z" fill="#1E293B"/><path d="M0 240 Q200 220 400 240 V260 H0Z" fill="#E2E8F0"/>`, "Northern lights over Iceland"),
    marrakech: () => svg(`<rect width="400" height="260" fill="#F59E0B"/><rect x="0" y="40" width="400" height="220" fill="#C2410C"/>${[60, 160, 260, 360].map((x) => `<path d="M${x - 30} 260 V150 a30 30 0 0 1 60 0 V260Z" fill="#7C2D12"/><path d="M${x - 20} 260 V156 a20 20 0 0 1 40 0 V260Z" fill="#FDE68A" opacity=".85"/>`).join("")}<rect y="230" width="400" height="30" fill="#0F766E"/>${Array.from({ length: 10 }, (_, i) => `<rect x="${i * 40 + 6}" y="236" width="28" height="18" fill="#FDE68A" opacity=".5"/>`).join("")}`, "Marrakech riad arches"),
    phuket: () => svg(`<rect width="400" height="260" fill="#FDBA74"/><circle cx="200" cy="120" r="44" fill="#FEF3C7"/><rect y="130" width="400" height="130" fill="#0E7490"/><path d="M0 130 L60 70 L120 130Z M300 130 L350 50 L400 130Z" fill="#14532D"/><path d="M150 200 q30 -10 60 0 l-8 14 h-44z" fill="#78350F"/><path d="M180 200 V150 l24 30z" fill="#FEF3C7"/>`, "Phuket longtail boat at sunset"),
    barcelona: () => svg(`<rect width="400" height="260" fill="#FDE68A"/><rect y="200" width="400" height="60" fill="#D97706"/>${[150, 185, 215, 250].map((x, i) => `<path d="M${x - 12} 200 L${x - 6} ${60 + i * 8} Q${x} ${40 + i * 6} ${x + 6} ${60 + i * 8} L${x + 12} 200Z" fill="#B45309"/>`).join("")}<circle cx="80" cy="70" r="26" fill="#FB923C"/>`, "Barcelona skyline"),
    bali: () => svg(`<rect width="400" height="260" fill="#BEF264"/>${Array.from({ length: 8 }, (_, i) => `<path d="M-20 ${40 + i * 30} Q200 ${10 + i * 32} 420 ${40 + i * 30} V260 H-20Z" fill="${["#84CC16", "#65A30D", "#4D7C0F", "#3F6212"][i % 4]}" stroke="#ECFCCB" stroke-width="3"/>`).join("")}`, "Bali rice terraces"),
    tokyo: () => svg(`<rect width="400" height="260" fill="#312E81"/>${Array.from({ length: 12 }, (_, i) => `<rect x="${i * 34}" y="${100 + (i % 4) * 25}" width="30" height="${160 - (i % 4) * 25}" fill="#1E1B4B"/>${Array.from({ length: 6 }, (_, k) => `<rect x="${i * 34 + 6}" y="${110 + (i % 4) * 25 + k * 20}" width="6" height="8" fill="${k % 2 ? "#F472B6" : "#FDE68A"}" opacity=".8"/>`).join("")}`).join("")}<path d="M300 30 L340 230 L260 230Z" fill="#FEF3C7" opacity=".15"/>`, "Tokyo skyline at night"),
    cruise: () => svg(`<rect width="400" height="260" fill="#7DD3FC"/><rect y="170" width="400" height="90" fill="#0284C7"/><path d="M60 170 h280 l-30 40 h-220z" fill="#F8FAFC"/><rect x="110" y="130" width="180" height="40" fill="#F8FAFC"/><rect x="140" y="100" width="120" height="30" fill="#F8FAFC"/>${Array.from({ length: 10 }, (_, i) => `<circle cx="${124 + i * 16}" cy="150" r="4" fill="#0369A1"/>`).join("")}<rect x="220" y="76" width="18" height="24" fill="#F97316"/>`, "Caribbean cruise ship"),
    lisbon: () => svg(`<rect width="400" height="260" fill="#FDBA74"/><rect y="110" width="400" height="30" fill="#60A5FA" opacity=".6"/>${Array.from({ length: 24 }, (_, i) => { const x = (i % 8) * 52 - 4, y = 130 + Math.floor(i / 8) * 46 - (i % 8) * 4; return `<rect x="${x}" y="${y}" width="48" height="50" fill="${["#FEF3C7", "#FED7AA", "#FDE68A", "#FECACA"][i % 4]}"/><path d="M${x - 4} ${y} L${x + 24} ${y - 14} L${x + 52} ${y}Z" fill="#C2410C"/>`; }).join("")}<rect x="250" y="210" width="110" height="40" rx="8" fill="#FACC15"/>`, "Lisbon rooftops and tram"),
    algarve: () => svg(`<rect width="400" height="260" fill="#7DD3FC"/><rect y="150" width="400" height="110" fill="#0284C7"/><path d="M220 0 Q200 120 260 190 L400 200 V0Z" fill="#D97706"/><path d="M0 230 Q200 200 400 235 V260 H0Z" fill="#FDE68A"/>`, "Algarve cliffs"),
    porto: () => svg(`<rect width="400" height="260" fill="#FDE68A"/>${Array.from({ length: 7 }, (_, i) => `<path d="M-10 ${80 + i * 22} Q200 ${50 + i * 24} 410 ${80 + i * 22}" stroke="${i % 2 ? "#4D7C0F" : "#65A30D"}" stroke-width="10" fill="none"/>`).join("")}<path d="M0 230 Q200 210 400 236 V260 H0Z" fill="#0E7490"/>`, "Douro valley vineyards"),
    athens: () => svg(`<rect width="400" height="260" fill="#FEF3C7"/><path d="M0 200 L120 150 L280 150 L400 200 V260 H0Z" fill="#A8A29E"/>${[0, 1, 2, 3, 4, 5].map((i) => `<rect x="${130 + i * 26}" y="90" width="12" height="60" fill="#F5F5F4"/>`).join("")}<path d="M120 90 L200 60 L280 90Z" fill="#F5F5F4"/>`, "Athens Acropolis"),
    srilanka: () => svg(`<rect width="400" height="260" fill="#FCD34D"/><rect y="140" width="400" height="120" fill="#0891B2"/><path d="M0 140 Q200 120 400 150 V170 H0Z" fill="#FEF3C7"/><path d="M80 260 Q90 160 70 90" stroke="#78350F" stroke-width="8" fill="none"/>${[-50, -15, 20, 55].map((a) => `<path d="M70 90 q${a} -20 ${a * 1.4} 18" stroke="#15803D" stroke-width="10" fill="none" stroke-linecap="round"/>`).join("")}`, "Sri Lanka beach"),
    paris: () => svg(`<rect width="400" height="260" fill="#C7D2FE"/><path d="M200 30 L230 230 H170Z" fill="none" stroke="#1E293B" stroke-width="6"/><path d="M182 140 h36 M176 180 h48 M188 90 h24" stroke="#1E293B" stroke-width="5"/><rect y="230" width="400" height="30" fill="#4D7C0F"/>`, "Eiffel Tower"),
  };
  window.__scene = (k) => (S[k] ? S[k]() : "");
  window.__renderScenes = (root) => root.querySelectorAll("[data-scene]").forEach((el) => { if (S[el.dataset.scene] && !el.firstElementChild) el.innerHTML = S[el.dataset.scene](); });
  window.__renderScenes(document);
})();
